#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "Tree\\Sitter\\Language\\Pack\\StructureItem")]
#[serde(default)]
pub struct StructureItem {
    /// The kind of structural item.
    #[php(prop, name = "kind")]
    #[serde(skip_serializing_if = "String::is_empty")]
    pub kind: String,
    /// The declared name of the item, if present.
    #[php(prop, name = "name")]
    pub name: Option<String>,
    /// Visibility modifier (e.g., `"pub"`, `"public"`, `"private"`).
    #[php(prop, name = "visibility")]
    #[serde(default)]
    pub visibility: Option<String>,
    /// Source span covering the entire item declaration.
    pub span: Span,
    /// Nested structural items (e.g., methods within a class).
    #[serde(default)]
    pub children: Vec<StructureItem>,
    /// Decorator or attribute names applied to the item.
    ///
    /// **Reserved: not yet populated.** Always empty, for every language.
    /// Recognising a decorator requires per-language grammar knowledge (a
    /// Python `decorated_definition` wrapper, Java/C# annotations, Rust
    /// attributes each have a different shape), which no extractor here
    /// implements yet. The field is kept rather than removed so a consumer's
    /// deserializer does not need updating once it is.
    #[php(prop, name = "decorators")]
    #[serde(default)]
    pub decorators: Vec<String>,
    /// Documentation comment attached to the item, if any.
    ///
    /// The text of the comment (or run of comments) immediately preceding
    /// the item, with no blank line in between, when that comment is
    /// classified as a doc comment. Multiple adjacent single-line doc
    /// comments (Rust `///`) are joined with `\n` in source order.
    ///
    /// Populated for Rust (`///`/`//!`), Java (`/** * /`), and JavaScript/
    /// TypeScript (`/** * /`). `None` for every other language, and for a
    /// preceding comment that is not in doc-comment form (a plain `#`
    /// comment in Python, Ruby, or Elixir) — Python's docstring convention is
    /// captured separately, as `DocstringInfo`, not through this field.
    #[php(prop, name = "docComment")]
    #[serde(alias = "docComment")]
    #[serde(default)]
    pub doc_comment: Option<String>,
    /// Full signature text of the item (e.g., function parameters and return type).
    ///
    /// The item's own source text from its start up to the start of its body
    /// (see `StructureItem.body_span`), trimmed of trailing whitespace —
    /// for example `fn add(a: i32, b: i32) -> i32` for a Rust function whose
    /// body is `{ a + b }`. `None` only when that text is empty, which does
    /// not happen for any item `StructureKind` currently reports. Populated
    /// for every language and kind this crate extracts structure for, since
    /// it is derived from `body_span`'s boundary rather than per-language
    /// syntax.
    #[php(prop, name = "signature")]
    #[serde(default)]
    pub signature: Option<String>,
    /// Source span covering only the body of the item, if distinct from the declaration.
    #[serde(alias = "bodySpan")]
    pub body_span: Option<Span>,
}

impl Default for StructureItem {
    fn default() -> Self {
        <tree_sitter_language_pack::StructureItem as Default>::default().into()
    }
}

#[php_impl]
impl StructureItem {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::default(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        kind: String,
        span: &Span,
        children: &ext_php_rs::types::ZendHashTable,
        decorators: Vec<String>,
        name: Option<String>,
        visibility: Option<String>,
        docComment: Option<String>,
        signature: Option<String>,
        bodySpan: Option<&Span>,
    ) -> PhpResult<Self> {
        let mut children_core_result: Vec<StructureItem> = Vec::new();
        for (_, item) in children.iter() {
            if let Some(parsed) = <&StructureItem as ext_php_rs::convert::FromZval>::from_zval(item) {
                children_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::default(
                    "Failed to convert array element to StructureItem".to_string(),
                ));
            }
        }
        let children_core: Vec<StructureItem> = children_core_result;
        Ok(Self {
            kind,
            name,
            visibility,
            span: span.clone(),
            children: children_core,
            decorators,
            doc_comment: docComment,
            signature,
            body_span: bodySpan.cloned(),
        })
    }

    pub fn get_kind(&self) -> String {
        self.kind.clone()
    }

    pub fn get_name(&self) -> Option<String> {
        self.name.clone()
    }

    pub fn get_visibility(&self) -> Option<String> {
        self.visibility.clone()
    }

    pub fn get_span(&self) -> Span {
        self.span.clone()
    }

    pub fn get_children(&self) -> Vec<StructureItem> {
        self.children.clone()
    }

    pub fn get_decorators(&self) -> Vec<String> {
        self.decorators.clone()
    }

    pub fn get_doc_comment(&self) -> Option<String> {
        self.doc_comment.clone()
    }

    pub fn get_signature(&self) -> Option<String> {
        self.signature.clone()
    }

    pub fn get_body_span(&self) -> Option<Span> {
        self.body_span.clone().map(Into::into)
    }

    pub fn set_body_span(&mut self, value: Option<&Span>) {
        self.body_span = value.map(|value| value.clone().into());
    }
}

#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "Tree\\Sitter\\Language\\Pack\\SymbolInfo")]
#[serde(default)]
pub struct SymbolInfo {
    /// The name of the symbol.
    #[php(prop, name = "name")]
    pub name: String,
    /// The kind of symbol (variable, function, class, etc.).
    #[php(prop, name = "kind")]
    #[serde(skip_serializing_if = "String::is_empty")]
    pub kind: String,
    /// Source span covering the symbol definition.
    pub span: Span,
    /// Explicit type annotation, if present in the source.
    #[php(prop, name = "typeAnnotation")]
    #[serde(alias = "typeAnnotation")]
    pub type_annotation: Option<String>,
    /// Documentation comment immediately preceding this symbol, resolved by
    /// the same walk `StructureItem.doc_comment` uses (see
    /// `doc_comment_at`) — never hard-coded `None`.
    ///
    /// Populated for Rust (`///`/`//!`), Java (`/** * /`), and JavaScript/
    /// TypeScript (`/** * /`) — the languages whose comment classification
    /// recognizes a doc-kind comment. `None` for every other language (e.g.
    /// Python, Go, Ruby, which have no doc-kind comment classification), and
    /// also `None` when a symbol in a supported language simply has no doc
    /// comment immediately above it.
    #[php(prop, name = "doc")]
    #[serde(default)]
    pub doc: Option<String>,
}

impl Default for SymbolInfo {
    fn default() -> Self {
        <tree_sitter_language_pack::SymbolInfo as Default>::default().into()
    }
}

#[php_impl]
impl SymbolInfo {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::default(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(name: String, kind: String, span: &Span, typeAnnotation: Option<String>, doc: Option<String>) -> Self {
        Self {
            name,
            kind,
            span: span.clone(),
            type_annotation: typeAnnotation,
            doc,
        }
    }

    pub fn get_name(&self) -> String {
        self.name.clone()
    }

    pub fn get_kind(&self) -> String {
        self.kind.clone()
    }

    pub fn get_span(&self) -> Span {
        self.span.clone()
    }

    pub fn get_type_annotation(&self) -> Option<String> {
        self.type_annotation.clone()
    }

    pub fn get_doc(&self) -> Option<String> {
        self.doc.clone()
    }
}

#[derive(Clone)]
#[php_class]
#[php(name = "Tree\\Sitter\\Language\\Pack\\Tree")]
pub struct Tree {
    inner: Arc<tree_sitter_language_pack::Tree>,
}

#[php_impl]
impl Tree {
    /// Return the root `Node` of this tree.
    pub fn root_node(&self) -> Node {
        Node {
            inner: Arc::new(self.inner.root_node()),
        }
    }

    /// Return a `TreeCursor` positioned at the root.
    pub fn walk(&self) -> TreeCursor {
        TreeCursor {
            inner: Arc::new(std::sync::Mutex::new(self.inner.walk())),
        }
    }
}

#[derive(Clone)]
#[php_class]
#[php(name = "Tree\\Sitter\\Language\\Pack\\TreeCursor")]
pub struct TreeCursor {
    inner: Arc<std::sync::Mutex<tree_sitter_language_pack::TreeCursor>>,
}

#[php_impl]
impl TreeCursor {
    /// Return the `Node` at the cursor's current position.
    pub fn node(&self) -> Node {
        Node {
            inner: Arc::new(self.inner.lock().unwrap().node()),
        }
    }

    /// Move the cursor to the first child of the current node.
    /// Returns `true` if a child existed.
    pub fn goto_first_child(&self) -> bool {
        self.inner.lock().unwrap().goto_first_child()
    }

    /// Move the cursor to the parent of the current node.
    /// Returns `true` if a parent existed.
    pub fn goto_parent(&self) -> bool {
        self.inner.lock().unwrap().goto_parent()
    }

    /// Move the cursor to the next sibling of the current node.
    /// Returns `true` if a sibling existed.
    pub fn goto_next_sibling(&self) -> bool {
        self.inner.lock().unwrap().goto_next_sibling()
    }

    /// Return the field name for the current node, if any.
    pub fn field_name(&self) -> Option<String> {
        self.inner.lock().unwrap().field_name()
    }
}

